				<div class="elementor-element elementor-element-518547fc elementor-widget elementor-widget-text-editor" data-id="518547fc" data-element_type="widget" data-e-type="widget" data-widget_type="text-editor.default">
									<p style="text-align:center;font-family:Space Grotesk,sans-serif;font-weight:700;font-size:12.5px;letter-spacing:2px;text-transform:uppercase;color:#7C3AED;margin:0"><span style="display:inline-block;width:22px;height:3px;background:linear-gradient(100deg,#FF2E7E,#7C3AED);border-radius:2px;margin-right:8px;vertical-align:middle"></span>The difference, in one table</p>								</div>
				<div class="elementor-element elementor-element-747012f9 elementor-widget elementor-widget-heading" data-id="747012f9" data-element_type="widget" data-e-type="widget" data-widget_type="heading.default">
